import java.util.*;
import java.io.*;

public class Main {
    static final int P = 998244353;
    static final int MOD = 1000000007;
    static final int B = 1000000;
    static long total_numbers = 0;
    static long count_numbers = 0;
    static long[] sum_arrays = new long[7];
    static int answer_value = 0;
    static List<Integer>[] array_list = new ArrayList[7];

    static {
        for (int i = 0; i < 7; i++) {
            array_list[i] = new ArrayList<>();
        }
    }

    static int mod_wrap(long d) {
        long res = d % P;
        if (res < 0) res += P;
        return (int) res;
    }

    static void generate(int level, long val) {
        total_numbers++;
        array_list[level].add(mod_wrap(total_numbers - val));
        if (level < 6) {
            for (int i = 0; i <= 9; i++) {
                generate(level + 1, val * 10 + i);
            }
        }
    }

    static int compute_value(int id, int f) {
        List<Integer> list = array_list[id];
        int pos = lowerBound(list, P - f);
        long sum = sum_arrays[id];
        long size = list.size();
        long result = ((long)f * size + sum - (long)P * (size - pos)) % MOD;
        if (result < 0) result += MOD;
        return (int) result;
    }

    static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    static void search(int depth, long v) {
        if (v > total_numbers) return;
        if (depth >= 1) {
            if (v * B > total_numbers / 10 && v * B + B - 1 <= total_numbers) {
                int t = 1;
                for (int i = 0; i <= 6; i++) {
                    answer_value = (answer_value + compute_value(i, mod_wrap(count_numbers - v * t))) % MOD;
                    t *= 10;
                }
                for (int i = 0; i <= 6; i++) {
                    count_numbers += array_list[i].size();
                }
                return;
            }
            answer_value = (answer_value + mod_wrap(++count_numbers - v)) % MOD;
        }
        int start = (depth == 0) ? 0 : 0;
        for (int i = start; i <= 9; i++) {
            search(depth + 1, v * 10 + i);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n_input = Long.parseLong(br.readLine());
        total_numbers = 0;
        generate(0, 0);
        for (int i = 0; i <= 6; i++) {
            Collections.sort(array_list[i]);
            for (int j = 0; j < array_list[i].size(); j++) {
                sum_arrays[i] += array_list[i].get(j);
            }
        }
        count_numbers = 0;
        answer_value = 0;
        search(0, 0);
        System.out.println(answer_value);
    }
}
